    mv_backward: ["p", "به مجهول نگاه کن و عقب برو: از کدام وضعِ پیشین می‌شد به آن رسید، و آن وضع از کدام؟", ["زنجیره به چیزی دانسته رسید؟ هر حلقه برگشت‌پذیر است؟"]],
