    mv_descent: ["p", "از یک نمونه می‌شود نمونهٔ کوچک‌ترِ هم‌نوع ساخت؟ حکم در گذر از n به n + 1 درست می‌ماند؟", ["کوچک‌ترین مثالِ نقضِ فرضی چه ویژگی‌ای دارد؟"]],
    mv_decompose: ["p", "می‌شود حالت‌ها را به چند دستهٔ جدا و جمعاً کامل شکست و هر کدام را جدا بست؟", ["فهرستِ حالت‌هایت کامل است؟ اصلِ دسته‌بندی‌اش روشن است؟"]],
    mv_analogy: ["p", "مسئلهٔ مرتبط یا مشابهِ ساده‌تری می‌شناسی؟ نتیجه یا روشش را این‌جا به کار می‌بری؟", ["قیاس کجا می‌شکند؟"]],
    mv_assume: ["u", "کدام مقدمه را بی‌آن‌که بگویی فرض کرده‌ای؟ آیا واقعاً در شرط هست؟", ["اگر آن فرض را برداری، چه عوض می‌شود؟"]],
    mv_control: ["c", "اگر فقط یک عامل را عوض کنی و بقیه را ثابت نگه داری، چه می‌بینی؟", ["گروهِ مقایسه کجاست؟"]],
    mv_measure: ["c", "آیا ابزارِ فعلی اصلاً می‌تواند دو حالت را از هم جدا کند؟", ["خطای سنجش از اثری که دنبالش هستی کوچک‌تر است؟"]],
    mv_anomaly: ["b", "کدام مشاهده با تصویرِ فعلی نمی‌خواند — و اگر جدی‌اش بگیری چه می‌گوید؟", ["وصلهٔ موردی می‌زنی یا چارچوب را عوض می‌کنی؟"]],
