    mv_auxproblem: ["p", "مسئلهٔ کمکی یا هم‌ارزی می‌سازی که حلش راه را باز کند؟", ["مسئلهٔ تازه واقعاً هم‌ارز است یا فقط شبیه؟"]],
    mv_symmetry: ["p", "مسئله نسبت به کدام جابه‌جایی‌ها تغییر نمی‌کند؟ تقارن را در نمادگذاری و راه حفظ می‌کنی؟", ["جوابت هم همان تقارن را دارد؟"]],
    mv_dimcheck: ["b", "نتیجه را وارسی می‌کنی؟ ابعادِ دو طرف یکی است؟ حالت‌های حدی جوابِ بدیهی می‌دهند؟", ["جای‌گذاری در شرط برقرار است؟"]],
    mv_recombine: ["p", "عنصرهای مسئله را به شکلِ تازه‌ای کنار هم می‌گذاری — تکه‌های هم‌نهشت، رابطهٔ بازگشتی، شمارش از دو راه؟", ["ترکیبِ تازه به مسئلهٔ کوچک‌ترِ هم‌نوع رسید؟"]],
    mv_vary: ["p", "مجهول یا داده‌ها یا هر دو را تغییر می‌دهی تا مسئله‌ای نزدیک و حل‌شدنی پدید آید؟", ["پلِ برگشت به مسئلهٔ اصلی کجاست؟"]],
